import React, { useRef, useEffect, useState } from 'react';
import { Canvas } from '@react-three/fiber';
import { OrbitControls, AsciiRenderer } from '@react-three/drei';
import { STLLoader } from 'three/examples/jsm/loaders/STLLoader';
import * as THREE from 'three';

export default function App() {
  return (
    <div style={{ height: '100vh', width: '100vw', background: '#000' }}>
      <Canvas
        camera={{ position: [0, 0, 15], fov: 45 }}
        style={{ width: '100%', height: '100%' }}
      >
        <color attach="background" args={['#000']} />
        <OrbitControls />
        <ambientLight intensity={0.8} />
        <directionalLight position={[5, 5, 5]} intensity={1} />
        <STLViewer path="./stls/model.stl" />
        <AsciiRenderer invert />
      </Canvas>
    </div>
  );
}

// Component to load and display the STL file
function STLViewer({ path }) {
  const [geometry, setGeometry] = useState(null);
  const meshRef = useRef();

  useEffect(() => {
    const loader = new STLLoader();
    loader.load(
      path,
      (geometry) => {
        geometry.center(); // Center the model in the scene
        setGeometry(geometry);
      },
      undefined,
      (error) => console.error('Error loading STL:', error)
    );
  }, [path]);

  // Adjust the scale dynamically to fit within the scene
  useEffect(() => {
    if (geometry && meshRef.current) {
      const boundingBox = new THREE.Box3().setFromObject(meshRef.current);
      const size = new THREE.Vector3();
      boundingBox.getSize(size);

      const maxDimension = Math.max(size.x, size.y, size.z);
      const scale = 10 / maxDimension; // Scale to fit the scene
      meshRef.current.scale.set(scale, scale, scale);
    }
  }, [geometry]);

  if (!geometry) return null;

  return (
    <mesh ref={meshRef} geometry={geometry}>
      <meshStandardMaterial color="#00ffff" wireframe={false} />
    </mesh>
  );
}
